import{_ as e,o as t,c as s,ag as a}from"./chunks/framework.D5hoimZQ.js";const g=JSON.parse('{"title":"生物医学","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/biomedicine/index.md","filePath":"topics/biomedicine/index.md"}'),n={name:"topics/biomedicine/index.md"};function o(r,i,c,l,h,d){return t(),s("div",null,[...i[0]||(i[0]=[a('<h1 id="生物医学" tabindex="-1">生物医学 <a class="header-anchor" href="#生物医学" aria-label="Permalink to &quot;生物医学&quot;">​</a></h1><blockquote><p>基因、细胞、衰老、感染、癌症——生命科学的前沿突破</p></blockquote><h2 id="文件列表" tabindex="-1">文件列表 <a class="header-anchor" href="#文件列表" aria-label="Permalink to &quot;文件列表&quot;">​</a></h2><ul><li><a href="/zhishiku-reading/topics/biomedicine/science-daily-2026-10-23-biomed.html">科学日报 2026-10-23（衰老/代谢/蛋白稳态）</a> — 第42期科学板块：<strong>低温延寿的分子路线</strong>——低温上调<strong>生物蝶呤合成酶 CAT-4（人源 GCH1）</strong>→ 提高<strong>BH2</strong>；BH2 作为<strong>可运输储库</strong>在<strong>肌肉产生→远端组织</strong>经<strong>补救酶 DHFR-1</strong> 转成 <strong>BH4</strong>→ 作为 <strong>PAH-1</strong> 必需辅因子促进<strong>酪氨酸合成</strong>→ <strong>延寿 + 抗蛋白聚集 + 保护神经元功能</strong>；<strong>只在肌肉提高 BH2 合成</strong>即足以在常温甚至高温下延寿并在远端抑制聚集；人细胞中补 <strong>BH2 或酪氨酸</strong>可减少 <strong>polyQ（亨廷顿）</strong> 与 <strong>TDP-43/FUS（ALS）</strong> 聚集 → <strong>把环境条件翻译成一条可搬运、可补充的代谢轴</strong>（Nature, 10.1038/s41586-026-11152-9）</li><li><a href="/zhishiku-reading/topics/biomedicine/science-daily-2026-10-20.html">科学日报 2026-10-20</a> — 第39期科学板块：肠道细胞命运由 <strong>Hes1 振荡频率</strong>编码（内源荧光报告显示隐窝—绒毛轴存在细胞类型特异的振荡频率梯度，受细胞周期相位/Wnt/Notch 调节；微流控调频即可改变类器官细胞类型组成）→ 信息编码在频率里、频率天然抗幅度噪声（Science, 10.1126/science.adt1928）</li><li><a href="/zhishiku-reading/topics/biomedicine/science-daily-2026-10-13.html">科学日报 2026-10-13</a> — 第36期：细菌&quot;端粒酶式&quot;逆转录抗病毒——DRT10 结合 ncRNA，以蛋白引物催化持续性串联重复 DNA 合成，冷冻电镜给出罕见的 2:1 结构（两 RT 单体夹一条拟对称 ncRNA，仅一侧产长重复），模板长度由两侧发夹锚点间距决定；系统发生把端粒酶与 DRT 家族归入同一单系支，提示共同起源（Nature, 10.1038/s41586-026-11250-8）</li><li><a href="/zhishiku-reading/topics/biomedicine/science-daily-2026-10-12.html">科学日报 2026-10-12</a> — 第35期：人类心脏发育单细胞+空间多组学图谱，定义 21 个组织生态位（TissueTypist），窦房结三种起搏细胞亚型 + 神经招引程序（Eph–ephrin、semaphorin–plexin），并定位 21 三体的发育扰动（Nature, 10.1038/s41586-026-11125-y）；肠道菌 <em>Bacteroides uniformis</em> 经奇数链脂肪酸十五烷酸抑制 HMG-CoA 还原酶、促肝胆固醇清除，缓解小鼠动脉粥样硬化（Nature, 10.1038/s41586-026-11142-x）</li><li><a href="/zhishiku-reading/topics/biomedicine/science-daily-2026-10-11.html">科学日报 2026-10-11</a> — 第34期：羽扇豆有毒喹诺里西啶生物碱（QA）的 15 步完整合成通路（类主要乳胶蛋白加速自发平衡、类氧化还原酶定立体选择性，可加速野生豆科去毒驯化；Science, 10.1126/science.aei5520），家犬表观遗传衰老与转座子（TE）失调反映体型相关寿命压缩（894 狗/1640 甲基化组时钟，性别轴在 X 染色体、体型轴在 TE；Science, 10.1126/science.aeb2986）</li><li><a href="/zhishiku-reading/topics/biomedicine/science-daily-2026-10-10.html">科学日报 2026-10-10</a> — 第33期：高尔基体来源 PI(3,4)P₂ 囊泡驱动线粒体融合（ER/mitofusin 位点模板；Science, 10.1126/science.adx9628），外膜 LPS 跨膜转运（LptB₂FGCADE 桥组装触发 TM-LptC 移动、调控 ATP 水解；Nature, 10.1038/s41586-026-11129-8），靶向 ZFP423 的 RNA 产热疗法在 GLP-1 减重中保住瘦体重（脂肪米色化 + 司美格鲁肽联用；PNAS, 10.1073/pnas.2618845123）</li><li><a href="/zhishiku-reading/topics/biomedicine/science-daily-2026-10-09.html">科学日报 2026-10-09</a> — 第32期：RNA 催化源于动态结构系综（76 个共存构象，RNase P；Nature, 10.1038/s41586-026-11140-z），肠道菌群&quot;启动&quot;疫苗发热（171 人纵向队列 + 无菌小鼠 + 类器官；Science, 10.1126/science.aea7733）</li><li><a href="/zhishiku-reading/topics/biomedicine/science-daily-2026-10-08.html">科学日报 2026-10-08</a> — 第31期：随人类迁徙、在工业化人群中消失的肠道微生物，Tsimane×Hadza 共享 1231 物种（Nature, 10.1038/s41586-026-11106-1）</li><li><a href="/zhishiku-reading/topics/biomedicine/science-daily-2026-09-22.html">科学日报 2026-09-22</a> — 第29期：sOrganellomics 多细胞器空间图谱，肝细胞在经典分区内混居（Science, 10.1126/science.ady6372）</li><li><a href="/zhishiku-reading/topics/biomedicine/science-daily-2026-09-21.html">科学日报 2026-09-21</a> — 第28期：无交换有性生殖（Nature）+ VIPR/CRISPR 病毒起源（Science）</li><li><a href="/zhishiku-reading/topics/biomedicine/2026-q3-breakthroughs.html">2026 Q3 突破</a> — 癌症（GATA6/aurB）、衰老（百岁老人/DEAF1/MTCH2）、感染（EatA/通用疫苗）、创伤（止血喷雾）</li><li><a href="/zhishiku-reading/topics/biomedicine/anastasis-cancer-cell-recovery.html">Anastasis：细胞凋亡逆转现象</a> — 癌细胞凋亡后&quot;复活&quot;机制，与癌症复发/转移/耐药的核心关系</li><li><a href="/zhishiku-reading/topics/biomedicine/chloroplast-endosymbiosis.html">叶绿体的内共生：被驯化的&quot;凝固阳光&quot;</a> — 内共生假说、光合作用光反应+卡尔文循环、&quot;谁驯化谁&quot;哲学、人工固碳延伸</li></ul>',4)])])}const m=e(n,[["render",o]]);export{g as __pageData,m as default};
